// NewCookie makes the session cookie for a signed-in user.
func NewCookie(token string, now time.Time) *http.Cookie {
	return &http.Cookie{
		Name:     CookieName,
		Value:    token,
		Path:     "/",
		Expires:  now.Add(Lifetime),
		HttpOnly: true,
		Secure:   true,
		SameSite: http.SameSiteStrictMode,
	}
}

arguments.new_string:
// Options tunes the session cookie. The zero value gives the defaults.
type Options struct {
	// Path limits the cookie to part of the site; "/" when empty.
	Path string
	// Domain shares the cookie with subdomains when set.
	Domain string
	// Lifetime overrides the package default when positive.
	Lifetime time.Duration
	// Lax allows the cookie on top-level links from other sites.
	Lax bool
}

// NewCookie makes the session cookie for a signed-in user.
func NewCookie(token string, now time.Time) *http.Cookie {
	return NewCookieWith(token, now, Options{})
}

// NewCookieWith makes the session cookie with the given options.
func NewCookieWith(token string, now time.Time, opts Options) *http.Cookie {
	path := opts.Path
	if path == "" {
		path = "/"
	}
	life := Lifetime
	if opts.Lifetime > 0 {
		life = opts.Lifetime
	}
	same := http.SameSiteStrictMode
	if opts.Lax {
		same = http.SameSiteLaxMode
	}
	return &http.Cookie{
		Name:     CookieName,
		Value:    token,
		Path:     path,
		Domain:   opts.Domain,
		Expires:  now.Add(life),
		HttpOnly: true,
		Secure:   true,
		SameSite: same,
	}
}
